"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { API_URL, ApiError, api, type JobInfo, type StudioStatus } from "@/lib/api";
import { fmtAgo, fmtBytes } from "@/lib/format";
import { JobLog } from "./JobLog";

/** The emscripten module generated by tools/sim/web_main.cpp (see ota-server/scripts/preview-build.sh). */
interface SimModule {
  _sim_init(lang: number, theme: number): void;
  _sim_frame(dtMs: number): void;
  _sim_pixels(): number;
  _sim_touch(x: number, y: number, down: number): void;
  _sim_screen(): number;
  _sim_relays(): number;
  _sim_scene(id: number): void;
  _sim_skip(sec: number): void;
  _sim_scene_count(): number;
  _sim_scene_name(i: number): number;
  _sim_fw_version(): number;
  UTF8ToString(ptr: number): string;
  HEAPU8: Uint8Array;
}
type SimFactory = (opts?: Record<string, unknown>) => Promise<SimModule>;

const W = 320;
const H = 480;

export function PreviewPanel({ token, onUnauthorized, onStudioChanged }: { token: string; onUnauthorized: () => void; onStudioChanged: () => void }) {
  const [studio, setStudio] = useState<StudioStatus | null>(null);
  const [jobId, setJobId] = useState<string | null>(null);
  const [lang, setLang] = useState(0);
  const [theme, setTheme] = useState(0);
  const [scale, setScale] = useState(1.5);
  const [scenes, setScenes] = useState<string[]>([]);
  const [fw, setFw] = useState("");
  const [relays, setRelays] = useState(0);
  const [state, setState] = useState<"idle" | "loading" | "running" | "error">("idle");
  const [error, setError] = useState<string | null>(null);
  const [reload, setReload] = useState(0);
  const canvas = useRef<HTMLCanvasElement>(null);
  const sim = useRef<SimModule | null>(null);

  const loadStudio = useCallback(async () => {
    try {
      const s = await api<StudioStatus>("/api/studio", token);
      setStudio(s);
      return s;
    } catch (e) {
      if (e instanceof ApiError && e.status === 401) onUnauthorized();
      else setError(e instanceof Error ? e.message : "Failed to load");
    }
  }, [token, onUnauthorized]);

  useEffect(() => {
    loadStudio().then((s) => {
      if (s?.busy?.kind === "preview") setJobId(s.busy.id);
    });
  }, [loadStudio]);

  const builtAt = studio?.preview?.builtAt ?? "";

  // load the compiled kiosk and run it; starts over when the build, language or theme change
  useEffect(() => {
    if (!builtAt) return;
    let alive = true;
    let raf = 0;
    let blobUrl = "";
    setState("loading");
    setError(null);
    (async () => {
      try {
        const res = await fetch(API_URL + "/api/preview/sim.js", { headers: { Authorization: `Bearer ${token}` }, cache: "no-store" });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        blobUrl = URL.createObjectURL(new Blob([await res.text()], { type: "text/javascript" }));
        const mod = (await import(/* webpackIgnore: true */ blobUrl)) as { default: SimFactory };
        const m = await mod.default();
        if (!alive) return;
        m._sim_init(lang, theme);
        sim.current = m;
        setScenes(Array.from({ length: m._sim_scene_count() }, (_, i) => m.UTF8ToString(m._sim_scene_name(i))));
        setFw(m.UTF8ToString(m._sim_fw_version()));
        setState("running");

        const ctx = canvas.current!.getContext("2d")!;
        let last = performance.now();
        let n = 0;
        const frame = (t: number) => {
          if (!alive) return;
          const dt = t - last;
          last = t;
          m._sim_frame(Math.min(100, Math.max(1, Math.round(dt))));
          const ptr = m._sim_pixels();
          const img = new ImageData(new Uint8ClampedArray(m.HEAPU8.buffer as ArrayBuffer, ptr, W * H * 4), W, H);
          ctx.putImageData(img, 0, 0);
          if (++n % 15 === 0) setRelays(m._sim_relays());
          raf = requestAnimationFrame(frame);
        };
        raf = requestAnimationFrame(frame);
      } catch (e) {
        if (alive) {
          setState("error");
          setError(e instanceof Error ? e.message : "Could not start the preview");
        }
      }
    })();
    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      sim.current = null;
      if (blobUrl) URL.revokeObjectURL(blobUrl);
    };
  }, [builtAt, lang, theme, token, reload]);

  function pos(e: React.PointerEvent<HTMLCanvasElement>) {
    const r = e.currentTarget.getBoundingClientRect();
    return { x: Math.round(((e.clientX - r.left) / r.width) * W), y: Math.round(((e.clientY - r.top) / r.height) * H) };
  }
  const down = (e: React.PointerEvent<HTMLCanvasElement>) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    const p = pos(e);
    sim.current?._sim_touch(p.x, p.y, 1);
  };
  const move = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (e.buttons) { const p = pos(e); sim.current?._sim_touch(p.x, p.y, 1); }
  };
  const up = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const p = pos(e);
    sim.current?._sim_touch(p.x, p.y, 0);
  };

  async function build() {
    setError(null);
    try {
      const j = await api<JobInfo>("/api/preview/build", token, { method: "POST" });
      setJobId(j.id);
      loadStudio();
      onStudioChanged();
    } catch (e) {
      if (e instanceof ApiError && e.status === 401) onUnauthorized();
      else setError(e instanceof Error ? e.message : "Failed");
    }
  }

  const onDone = useCallback(async (j: JobInfo) => {
    await loadStudio();
    onStudioChanged();
    if (j.status === "ok") setReload((n) => n + 1);
  }, [loadStudio, onStudioChanged]);

  const running = studio?.busy?.kind === "preview";
  const other = studio?.busy && studio.busy.kind !== "preview";

  return (
    <section className="stack">
      <div className="card stack">
        <div className="row between wrap">
          <h2>Kiosk preview</h2>
          <div className="row wrap">
            {studio?.preview && <span className="muted small">built {fmtAgo(studio.preview.builtAt)} · v{studio.preview.version} · {fmtBytes(studio.preview.size)}</span>}
            <button className="btn primary" onClick={build} disabled={!!running || !!other || studio?.toolchain.emsdk === false}>
              {running ? "Building…" : studio?.preview ? "Rebuild from my code" : "Build preview"}
            </button>
          </div>
        </div>
        <p className="muted small">
          This is the real kiosk UI code (LVGL, the same <code>main.cpp</code> as the firmware) compiled to WebAssembly from the <b>saved</b> files in the Code tab, running in your browser. Click and drag on the screen like a touch panel.
          Payments and the relay controller are emulated.
        </p>
        {other && <p className="alert warn">A {studio!.busy!.kind} build is running; wait for it to finish.</p>}
        {studio && !studio.toolchain.emsdk && <p className="alert error">Emscripten is not installed on the server.</p>}
        {error && <p className="alert error" role="alert">{error}</p>}

        {!studio?.preview && !running && !jobId && <p className="alert warn">No preview yet. Press <b>Build preview</b> (the first build compiles LVGL and takes a few minutes; later ones are much faster).</p>}

        {studio?.preview && (
          <div className="preview">
            <div className="phone">
              <canvas
                ref={canvas}
                width={W}
                height={H}
                style={{ width: W * scale, height: H * scale }}
                onPointerDown={down}
                onPointerMove={move}
                onPointerUp={up}
                onPointerCancel={up}
                aria-label="Kiosk screen"
              />
              {state === "loading" && <p className="muted small">Starting…</p>}
            </div>
            <div className="stack side">
              <div className="stack tight">
                <strong>Jump to screen</strong>
                <div className="chips">
                  {scenes.map((s, i) => <button key={s} className="btn small" onClick={() => sim.current?._sim_scene(i)}>{s}</button>)}
                </div>
              </div>
              <div className="row wrap">
                <div className="seg" role="group" aria-label="Language">
                  <button className={lang === 0 ? "on" : ""} onClick={() => setLang(0)}>Bahasa</button>
                  <button className={lang === 1 ? "on" : ""} onClick={() => setLang(1)}>English</button>
                </div>
                <div className="seg" role="group" aria-label="Theme">
                  <button className={theme === 0 ? "on" : ""} onClick={() => setTheme(0)}>Dark</button>
                  <button className={theme === 1 ? "on" : ""} onClick={() => setTheme(1)}>Light</button>
                </div>
                <div className="seg" role="group" aria-label="Size">
                  {[1, 1.5, 2].map((s) => <button key={s} className={scale === s ? "on" : ""} onClick={() => setScale(s)}>{s}×</button>)}
                </div>
              </div>
              <div className="row wrap">
                <button className="btn small" onClick={() => sim.current?._sim_skip(300)}>Skip 5 min of the running cycle</button>
                <button className="btn small" onClick={() => setReload((n) => n + 1)}>Restart kiosk</button>
              </div>
              <p className="muted small">
                Firmware v{fw || "?"} · relays: {[1, 2, 3, 4, 5, 6, 7, 8].map((c) => <span key={c} className={`relay ${relays & (1 << (c - 1)) ? "on" : ""}`}>{c}</span>)}
                <br />Relays 1–4 wash, 5–8 dry.
              </p>
            </div>
          </div>
        )}
      </div>

      {jobId && (
        <div className="card stack">
          <JobLog token={token} jobId={jobId} onDone={onDone} onUnauthorized={onUnauthorized} />
        </div>
      )}
    </section>
  );
}
